-- MFDCO Country v25 compact verification
select table_name from information_schema.tables where table_schema='public' and table_name in ('countries','country_members','country_user_preferences','country_documents','country_entities','country_links','country_metrics','country_work_adoptions','international_organizations','international_organization_members','international_organization_treaties','country_market_history') order by table_name;

select table_name,column_name,data_type from information_schema.columns where table_schema='public' and ((table_name='country_work_adoptions' and column_name in ('branch_names','unit_names','unit_name')) or (table_name='international_organizations' and column_name in ('join_mode','headquarters','founded','website','founder_country_id')) or (table_name='country_media' and column_name in ('display_name','download_access_override','download_terms_override','updated_at')) or (table_name='countries' and column_name in ('population','area_km2','strength_score','flag_key','cover_key'))) order by table_name,column_name;

select p.proname,pg_get_function_identity_arguments(p.oid) arguments from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('mfdco_save_country','mfdco_my_country_access','mfdco_public_country_feed','mfdco_public_market_snapshots','mfdco_country_dashboard_overview','mfdco_set_country_media_defaults','mfdco_public_works_for_adoption') order by p.proname;
